//! Protocol Buffers (`proto3`) bindings generated by `prost` (`rules_rust_prost`)
//! from `proto/tec11.proto` (`package tec11;`, `.tec11` binary snapshot files).

pub use prost::DecodeError;
pub use prost::Message;
pub use tec11_schema_proto::tec11::*;

pub type RockKindOneof = rock::Kind;
pub type PlanetStageOneof = planet_snapshot::Stage;
pub type ConceptKind = concept::Kind;

pub trait MetamorphicFaciesExt {
    fn from_rock_name(name: &str) -> MetamorphicFacies;
    fn rock_name(self) -> &'static str;
}

impl MetamorphicFaciesExt for MetamorphicFacies {
    fn from_rock_name(name: &str) -> Self {
        match name {
            "pelite" => Self::Pelite,
            "psammite" => Self::Psammite,
            "psephite" => Self::Psephite,
            "blueschist" => Self::Blueschist,
            "greenschist" => Self::Greenschist,
            "amphibolite" => Self::Amphibolite,
            "eclogite" => Self::Eclogite,
            "hornfels" => Self::Hornfels,
            "granulite" => Self::Granulite,
            "marble" => Self::Marble,
            _ => Self::Greenschist,
        }
    }

    fn rock_name(self) -> &'static str {
        match self {
            Self::Pelite => "pelite",
            Self::Psammite => "psammite",
            Self::Psephite => "psephite",
            Self::Blueschist => "blueschist",
            Self::Greenschist => "greenschist",
            Self::Amphibolite => "amphibolite",
            Self::Eclogite => "eclogite",
            Self::Hornfels => "hornfels",
            Self::Granulite => "granulite",
            Self::Marble => "marble",
        }
    }
}

pub trait GeologicalTileExt {
    fn thickness(&self) -> f32;
    fn elevation(&self) -> f32;
}

impl GeologicalTileExt for GeologicalTile {
    fn thickness(&self) -> f32 {
        self.layers.iter().map(|l| l.thickness).sum()
    }

    fn elevation(&self) -> f32 {
        self.bottom + self.thickness()
    }
}

pub trait PlanetSnapshotExt: Sized {
    fn encode_bytes(&self) -> Vec<u8>;
    fn decode_bytes(bytes: &[u8]) -> Result<Self, prost::DecodeError>;
    fn geological_tiles(&self) -> Option<Vec<&GeologicalTile>>;
    fn tectonics_ticks(&self) -> u32;
}

impl PlanetSnapshotExt for PlanetSnapshot {
    fn encode_bytes(&self) -> Vec<u8> {
        <Self as prost::Message>::encode_to_vec(self)
    }

    fn decode_bytes(bytes: &[u8]) -> Result<Self, prost::DecodeError> {
        <Self as prost::Message>::decode(bytes)
    }

    fn geological_tiles(&self) -> Option<Vec<&GeologicalTile>> {
        match &self.stage {
            Some(planet_snapshot::Stage::Tectonics(t)) => Some(t.tiles.iter().collect()),
            Some(planet_snapshot::Stage::Prehistory(p)) => {
                Some(p.tiles.iter().filter_map(|pt| pt.geology.as_ref()).collect())
            }
            Some(planet_snapshot::Stage::History(h)) => h
                .prehistory_base
                .as_ref()
                .map(|p| p.tiles.iter().filter_map(|pt| pt.geology.as_ref()).collect()),
            None => None,
        }
    }

    fn tectonics_ticks(&self) -> u32 {
        match &self.stage {
            Some(planet_snapshot::Stage::Tectonics(t)) => t.tectonics_ticks,
            Some(planet_snapshot::Stage::Prehistory(p)) => p.tectonics_ticks,
            Some(planet_snapshot::Stage::History(h)) => h
                .prehistory_base
                .as_ref()
                .map(|p| p.tectonics_ticks)
                .unwrap_or(0),
            None => 0,
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_planet_snapshot_prost_roundtrip() {
        let snap = PlanetSnapshot {
            rng_state_16b: (1u8..=16u8).collect(),
            grid_size: 5,
            radius_km: 6400.0,
            spin: 1.0,
            tilt_deg: 23.5,
            stage: Some(PlanetStageOneof::Tectonics(TectonicsStage {
                tectonics_ticks: 12,
                atmosphere_ticks_remaining: 0,
                life_ticks_remaining: 3,
                people_ticks_remaining: 8,
                tiles: vec![
                    GeologicalTile {
                        bottom: -10.5,
                        mountainosity: 0.0,
                        layers: vec![RockLayer {
                            rock: Some(Rock {
                                kind: Some(RockKindOneof::Igneous(IgneousRock {
                                    is_intrusive: false,
                                    felsity: 0.5,
                                    quartzity: None,
                                    sulfidity: None,
                                })),
                            }),
                            thickness: 5.0,
                        }],
                    },
                    GeologicalTile {
                        bottom: -35.0,
                        mountainosity: 4.25,
                        layers: vec![
                            RockLayer {
                                rock: Some(Rock {
                                    kind: Some(RockKindOneof::Metamorphic(MetamorphicRock {
                                        facies: MetamorphicFacies::Greenschist as i32,
                                        toughness: 0.65,
                                        felsity: Some(0.75),
                                        calcity: None,
                                        bogginess: None,
                                        quartzity: Some(0.45),
                                        sulfidity: None,
                                        salinity: None,
                                    })),
                                }),
                                thickness: 25.0,
                            },
                            RockLayer {
                                rock: Some(Rock {
                                    kind: Some(RockKindOneof::Sedimentary(SedimentaryRock {
                                        clasticity: 2.0,
                                        felsity: Some(0.7),
                                        calcity: Some(0.8),
                                        bogginess: Some(0.0),
                                        quartzity: None,
                                        sulfidity: None,
                                        salinity: Some(0.25),
                                    })),
                                }),
                                thickness: 12.0,
                            },
                        ],
                    },
                ],
                groups: vec![LithosphericGroup {
                    tile_ids: vec![0, 1, 42, 2431],
                    velocity: Some(Vec3 {
                        x: 0.01,
                        y: -0.02,
                        z: 0.005,
                    }),
                }],
                ridges: vec![SpreadingRidgeArc {
                    start: Some(Vec3 {
                        x: 1.0,
                        y: 0.0,
                        z: 0.0,
                    }),
                    end: Some(Vec3 {
                        x: 0.0,
                        y: 1.0,
                        z: 0.0,
                    }),
                    velocity: Some(Vec3 {
                        x: 0.0,
                        y: 0.0,
                        z: 0.01,
                    }),
                    age_ticks: 4,
                }],
            })),
        };

        let bytes = snap.encode_bytes();
        assert!(!bytes.is_empty());
        let decoded = PlanetSnapshot::decode_bytes(&bytes).expect("valid prost proto3 wire format");
        assert_eq!(decoded, snap);
        assert_eq!(decoded.tectonics_ticks(), 12);
        let geo_tiles = decoded.geological_tiles().expect("has tiles");
        assert_eq!(geo_tiles.len(), 2);
        assert!((geo_tiles[0].elevation() - (-5.5)).abs() < 1e-5);
        assert!((geo_tiles[1].elevation() - 2.0).abs() < 1e-5);
    }
}
